import axios from "axios";
import { useState } from "react";
import * as XLSX from 'xlsx';


function App() {

  const [msg, setmsg] = useState("")
  const [status, setstatus] = useState(false)
  const [emailList, setemailList] = useState([]);
  const [fileName, setFileName] = useState("");

  function handlemsg(evt){
    setmsg(evt.target.value)
  }

  function Send(){
    setstatus(true);
    axios.post("http://localhost:5000/sendemail", {msg:msg, emailList: emailList})
    .then(function (data){
      if(data.data === true){
        alert("Email sent successfully");
      }
      else{
        alert("Failed to send email");
      }
    });
  }

  function handleFile(){
    const fileInput = document.getElementById('fileInput');

    fileInput.addEventListener('change', (event) => {
      const file = event.target.files[0];
      console.log('Selected file:', file);
      setFileName(file.name);

      const reader = new FileReader();
      reader.onload = (evt) => {
        const data = evt.target.result;
        const workbook = XLSX.read(data, { type: 'binary' });
        const sheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[sheetName];
       const emailList = XLSX.utils.sheet_to_json(worksheet, {header: "A"})
       const count = emailList.length;
       const totalemail = emailList.map((item) => item.A);
       setemailList(totalemail);
       console.log('Email list:', emailList);
       console.log('Total recipients:', count);
      };
    }
    )
  }
  return (
  
  <>
  <div className="min-h-screen bg-black text-white flex flex-col">

    {/* Header */}
    <header className="pt-14 pb-10 text-center">
      <h1 className="text-4xl md:text-5xl font-semibold tracking-[0.18em]">
        BulkMail
      </h1>

      <p className="mt-4 text-sm md:text-base text-zinc-400 tracking-[0.08em]">
        Send multiple emails. Simply. Efficiently.
      </p>
    </header>


    {/* Main Content */}
    <main className="w-full max-w-3xl mx-auto px-6 flex-1">

      {/* Message */}
      <div className="mb-10">
        <label className="block mb-3 text-xs font-medium text-[#D4AF37] tracking-[0.25em]">
          MESSAGE
        </label>

        <textarea
          value={msg}
          onChange={handlemsg}
          placeholder="Write your message..."
          className="
            w-full
            h-52
            bg-zinc-950
            border
            border-zinc-800
            rounded-xl
            p-5
            text-sm
            text-white
            placeholder:text-zinc-600
            tracking-wide
            resize-none
            outline-none
            focus:border-[#D4AF37]
            transition
          "
        />
      </div>


      {/* File Upload */}
      <div className="mb-8">
        <label className="block mb-3 text-xs font-medium text-[#D4AF37] tracking-[0.25em]">
          RECIPIENTS
        </label>

        <label
          htmlFor="fileInput"
          className="
            group
            w-full
            min-h-32
            border
            border-dashed
            border-zinc-700
            rounded-xl
            bg-zinc-950
            flex
            flex-col
            items-center
            justify-center
            cursor-pointer
            hover:border-[#D4AF37]
            transition
          "
        >
          <span className="text-sm text-zinc-300 tracking-wide">
            {fileName || "Choose your recipient file"}
          </span>

          <span className="mt-2 text-xs text-zinc-600 tracking-wider">
            XLSX • XLS • CSV
          </span>

          <span
            className="
              mt-5
              px-5
              py-2
              rounded-md
              border
              border-[#D4AF37]
              text-[#D4AF37]
              text-xs
              tracking-[0.15em]
              uppercase
              group-hover:bg-[#D4AF37]
              group-hover:text-black
              transition
            "
          >
            Browse
          </span>
        </label>

        <input
          id="fileInput"
          type="file"
          accept=".xlsx,.xls,.csv"
          onChange={handleFile}
          className="hidden"
        />
      </div>


      {/* Email Count */}
      <div className="flex items-center justify-between py-5 border-y border-zinc-900">

        <span className="text-xs text-zinc-500 tracking-[0.15em] uppercase">
          Total recipients
        </span>

        <span className="text-lg font-medium text-[#D4AF37]">
          {emailList.length}
        </span>

      </div>


      {/* Send Button */}
      <div className="flex justify-center mt-10 mb-16">

        <button
          onClick={Send}
          className="
            px-10
            py-3.5
            bg-[#D4AF37]
            text-black
            rounded-md
            text-sm
            font-semibold
            tracking-[0.12em]
            uppercase
            hover:bg-[#E5C45A]
            active:scale-95
            transition
          "
        >
          {status ? "Sending..." : "Send Emails"}
        </button>

      </div>

    </main>


    {/* Footer */}
    <footer className="pb-8 text-center">

      <p className="text-[10px] text-zinc-700 tracking-[0.35em]">
        BULKMAIL
      </p>

    </footer>

    </div>
    </>

);

}

export default App;
